import{_ as p,c as e,o as r,af as h}from"./chunks/framework.BKeRpnBD.js";const b=JSON.parse('{"title":"無妄","description":"高岛易断 - 無妄","frontmatter":{"title":"無妄","description":"高岛易断 - 無妄"},"headers":[],"relativePath":"zh/classics/takashima/025.md","filePath":"zh/classics/takashima/025.md"}'),i={name:"zh/classics/takashima/025.md"};function l(n,a,d,t,s,c){return r(),e("div",null,[...a[0]||(a[0]=[h('<h1 id="無妄" tabindex="-1">無妄 <a class="header-anchor" href="#無妄" aria-label="Permalink to “無妄”">​</a></h1><h2 id="無妄-1" tabindex="-1">無妄 <a class="header-anchor" href="#無妄-1" aria-label="Permalink to “無妄”">​</a></h2><h2 id="卦辞" tabindex="-1">卦辞 <a class="header-anchor" href="#卦辞" aria-label="Permalink to “卦辞”">​</a></h2><p>元亨利贞。其匪正有眚，不利有攸往。</p><h2 id="卦辞注" tabindex="-1">卦辞注 <a class="header-anchor" href="#卦辞注" aria-label="Permalink to “卦辞注”">​</a></h2><p>“元亨利贞”，是谓四德惟《乾》全具，余卦曰“元亨利贞”者，皆从《乾》来也。“元亨利贞”，统言之，一正而已，正则无妄矣，故曰《无妄》“元亨利贞”。此乃自然之实理，受之于天，不容间以一毫私意，间以私意，即非正矣，非正则妄，妄必多过，故“有眚”也。既已无妄，不宜妄有所往，故曰“不利有攸往”。</p><h2 id="象辞" tabindex="-1">象辞 <a class="header-anchor" href="#象辞" aria-label="Permalink to “象辞”">​</a></h2><p>天下雷行，物与无妄，先王以茂对时育万物。</p><h2 id="象辞注" tabindex="-1">象辞注 <a class="header-anchor" href="#象辞注" aria-label="Permalink to “象辞注”">​</a></h2><p>“天下雷行”，阳气勃发，鼓动万物，万物与之共动，蛰虫振，草木萌，有翼者飞，有足者走，无不勃然发育，各正性命，而无有差妄，谓之“物与无妄”。法天之象，以茂对天时者，布顺时之化，以养育万物者，赞生物之功，使时行物生，物物各全其所与，春生养长，咸得其宜，斯吾心中之万物皆备，而天下之万物并育。此所谓尽性尽物也。</p><h2 id="占断" tabindex="-1">占断 <a class="header-anchor" href="#占断" aria-label="Permalink to “占断”">​</a></h2><p>○　问时运：目下运得其时，百事咸宜，吉。</p><p>○　问商业：正如大旱望雨，响雷一声，人人翘望。货物一到，无不旺销，百般获利，大吉。</p><p>○　问家宅：此宅中时有作响，但无忌碍，屋运甚旺，人口繁盛，吉。</p><p>○　问战征：有风雷席卷之势，务须正正之旗，堂堂之阵，若欲以诈取胜，反恐有祸。</p><p>○　问疾病：是胸有积物，动而未化，宜随时运动，物自消化，“勿药有喜”。</p><p>○　问行人：现时已动身，即日可归。</p><p>○　问婚嫁：两家素有往来，门媚相对，大吉。</p><p>○　问六甲：生男，临时安产，吉。</p><p>○　问失物：或鼓旁，或磨下，或并臼之侧，寻之可得。</p><p>○　问天时：一雨即晴。</p><h2 id="初九解" tabindex="-1">初九解 <a class="header-anchor" href="#初九解" aria-label="Permalink to “初九解”">​</a></h2><p>初为内卦之主，《震》初之刚，自《乾》而来，故《彖传》曰“刚自外来”。初阳始生，诚一未分，不杂未起，率性而动，动罔不臧，以其动合乎天也；由兹而往，往无不吉焉，故曰“往吉”。《象传》曰“往得志也”，诚无不通，志无不遂，故往而得志也。</p><h2 id="初九占" tabindex="-1">初九占 <a class="header-anchor" href="#初九占" aria-label="Permalink to “初九占”">​</a></h2><p>○　问时运：目下吉，但宜出而有为，不宜杜守家居。</p><p>○　问商业：利行商，不利坐贾。</p><p>○　问家宅：宜迁居，吉。</p><p>○　问战征：宜进攻，吉。</p><p>○　问疾病：宜出外就医，吉。</p><p>○　问行人：或有事他往，吉。</p><p>○　问六甲：生男，来月可产，吉。</p><p>○　问婚姻：赘婿吉。</p><p>○　问失物：宜往外寻之。</p><h2 id="初九案例" tabindex="-1">初九案例 <a class="header-anchor" href="#初九案例" aria-label="Permalink to “初九案例”">​</a></h2><p>角抵士毛谷村六介者，土州人，体格肥大，重量三十贯余。明治十七年某月，余与友人某氏，见角解于两国回向院，友人特爱毛谷村，请占其进步。缀得《无妄》之《否》。</p><p>断曰：此卦上《乾》下《震》，《乾》为父，《震》为长男，有上体大而健，下体小而弱之象。又《震》为足，初爻变《震》体败，必主足疾，恐此人伤足。下爻六二曰“不耕获，不菑畲”，是农而废其业也。由是观之，力士明年殆将废其角解，而转就他业矣。翌十八年，六介果折足而转他业。</p><h2 id="六二解" tabindex="-1">六二解 <a class="header-anchor" href="#六二解" aria-label="Permalink to “六二解”">​</a></h2><p>《乾》为郊野，《震》为禾稼，故爻取农象。耕而有获，菑而有畲，原非意外期望；然以耕而期获，以菑而期畲，心有期望，无妄之望，即是妄也。爻曰“不耕获，不菑畲”，谓当耕则耕，耕未尝有心于获，宜菑则菑，菑未尝有意于畲，任乎先天，不假后起，犹之谋道者非为干禄，修德者非为求名，尽其在我，不计外来。如是则为《无妄》，《无妄》则“利有攸往”，言无妄心，自无妄行，则往无不利也。《象传》曰“未富也”，谓二爻居柔得正，中虚无欲，未尝有心于富也；未富而不妄意于富，此即所谓《无妄》也。</p><h2 id="六二占" tabindex="-1">六二占 <a class="header-anchor" href="#六二占" aria-label="Permalink to “六二占”">​</a></h2><p>○　问时运：目下运得其正，自有意外财饷，大利。</p><p>○　问商业：不谋而获，却得大利，吉。</p><p>○　问家宅：此宅想是承继之产，或为人经管庄舍。</p><p>○　问战征：前途倒戈，有不胜而胜之象。</p><p>○　问疾病：“勿药有喜”。</p><p>○　问婚姻：是招赘之亲。</p><p>○　问行人：在外得利，一时未归。</p><p>○　问六甲：生女。</p><h2 id="六二案例" tabindex="-1">六二案例 <a class="header-anchor" href="#六二案例" aria-label="Permalink to “六二案例”">​</a></h2><p>明治十四年一月，余浴于热海，同浴者有花族岛津公及成岛柳北等，暇时相与攀谈。既而大隈伊藤进上诸君亦来浴，时大隈君顾众曰：方今俄清两国互争境界，两国派出委员，议论不决，和战未定，各国之所注目也。高岛氏幸为一占。余乃应命，筮得《无妄》之《履》。</p><p>断曰：清为我邻，以内卦充之，外卦为俄。《无妄》内卦为《震》，《震》为木，譬犹木槌；外卦为《乾》，《乾》为金，譬犹巨钟。今观清国政府，力尚不足，以清拒俄，譬犹以木槌叩巨钟，巨钟依然，而木槌早已摧矣。故知清必不抗俄，必以和议结局也，明矣。爻辞曰“不耕获，不菑畲”，俄之利，清之灾也。一时座客，或拍手赞叹，或疑虑不服，后果如此占，使疑者亦服焉。</p><p>东京青山有一富商，自二三世来，分为本末两家，末家常守勤俭，家业益昌，本家不善治产，游惰相承，家业凋落。末家虽屡屡分金相助，如运雪填井，其消立尽。本家计穷，窃欲并吞末家之产，召唤末家主人相商曰：汝家之所有，非汝家所自有也，曩时曾从我本家分而与之也。今本家困乏若此，汝盍归还之乎？汝其了此意乎？末家主人惊愕，虽百方苦陈不听。本家主人，以事不谐，将欲讼之官，末家主人，就余请占其吉凶。筮得《无妄》之《履》。</p><p>断曰：此卦上《乾》下《震》，《乾》为金，《震》为木，金为本家，木为末家，末家持木，以击本家之金，末家必不胜，其理昭昭也。爻辞曰“不耕获，不菑畲”，耕者必获，菑者必畲，常也。今日耕而不获，菑而不畲，虽为理之所无，往往为事之所或有。以君家数代勤俭，贮蓄财产，一旦拱手而偿诸本家，固属心之所不甘，故曰“无妄灾也”。今既得此占，宜如其意而让之，独怀资金，另兴一家。爻曰“则利有攸往”，君从此孜孜勉励，当必再致繁昌也。末家主人，果从余言，举财产让之，另开一户，励精家业，未几又获兴起。</p><h2 id="六三解" tabindex="-1">六三解 <a class="header-anchor" href="#六三解" aria-label="Permalink to “六三解”">​</a></h2><p>“无妄之灾”，谓非己之所致而灾，天数之灾厄，或有不可免也。六三位不中正，故事出意外，有如“或系之牛”。“系”者而曰“或”，原不知为谁氏之牛也；“行人”，行路之人也，见其牛以为无主也，而窃得之。在邑之人，未之知也，而捕者则必就邑人而诘之，是邑人无故而受灾也，即所谓“无妄之灾”也。三至五《离》，《离》为牛，下互《艮》，《艮》为拘，上互《巽》，《巽》为绳，有系牛之象。《乾》健行，象行人，《震》为守，象邑人。《乾》之行，至上止，上为行人，故上曰“行有眚”，是得牛而遭眚也。《震》之守，属于三，三为邑人，故曰“邑人之灾”。上得其牛，而三罹其灾，是三为“无妄之灾”。上之《象》曰“穷之灾也”，上乃自致之灾，所谓自作之孽也。《象传》曰“邑人灾也”，此意外之灾，惟顺受焉而已。</p><h2 id="六三占" tabindex="-1">六三占 <a class="header-anchor" href="#六三占" aria-label="Permalink to “六三占”">​</a></h2><p>○　问时运：目下运值尴尬，防有意外之事，宜谨慎。</p><p>○　问商业：防他人占利，而己耗财。</p><p>○　问家宅：此宅恐为外人侵占。</p><p>○　问战征：行军得胜，守军防有损败。</p><p>○　问疾病：此病恐是外来人传染，可虑。</p><p>○　问行人：归则归矣，恐家人有灾。</p><p>○　问婚嫁：宜与远人结亲，吉。</p><p>○　问失物：已被行人拾去。</p><h2 id="六三案例" tabindex="-1">六三案例 <a class="header-anchor" href="#六三案例" aria-label="Permalink to “六三案例”">​</a></h2><p>一日友人某，突然来访曰：仆近与朋友某，共计一商业，书来约今日会晤，今忽以家事混杂谢绝，其中或有变计乎？请劳一筮。筮得《无妄》之《同人》。</p><p>断曰：爻辞谓“或系之牛，行人之得，邑人之灾”，按《离》为牛，亦为女，观此知其家必有远来亲友，以妇女寄托也。此女象取《离》卦，必有离绝之事，且《离》为孕，或女已怀孕矣。“行人之得”，是与行人而皆奔也，在某住所，非畜牛之地，故知其必为女也。“系”者，即寄托之谓也，“邑人”者，即君之友也。然此友受此女之寄，所谓“邑人之灾”，恐难免矣。某所称家事混杂，殆即此欤？友人惊余言奇异而归，后数日，来谢曰：过日占辞，不误一语，悉合事实。</p><h2 id="九四解" tabindex="-1">九四解 <a class="header-anchor" href="#九四解" aria-label="Permalink to “九四解”">​</a></h2><p>四阳刚而居《乾》体，刚而无私，无妄者也。然位当上下之交，初《乾》阳刚犹柔，恐固守未定，或有偶涉于妄者乎？故诫之曰“可贞”。盖以《乾》之健，乘《无妄》之体，更当以《乾》之贞，葆无妄之诚。斯无妄之理，静以存之，固以守之，自无过失矣，故曰“无咎”。《象传》曰“固有之也”，无妄之心，即天心也，秉于生初，非由外铄，故曰“固有”也。</p><h2 id="九四占" tabindex="-1">九四占 <a class="header-anchor" href="#九四占" aria-label="Permalink to “九四占”">​</a></h2><p>○　问时运：目下气运平顺，循分则有获，妄动则有咎。</p><p>○　问商业：坚守旧业，自然亨通。</p><p>○　问家宅：此宅本是祖基，宜永保之，毋坠。</p><p>○　问战征：已占入外卦之地，宜坚守城池，切勿妄进。</p><p>○　问疾病：此时宜安静调养，来月“勿药”而愈。</p><p>○　问行人：一时未归，在外无咎。</p><p>○　问六甲：生男。</p><p>○　问失物：必可复得。</p><h2 id="九四案例" tabindex="-1">九四案例 <a class="header-anchor" href="#九四案例" aria-label="Permalink to “九四案例”">​</a></h2><p>某贵显来，请占气运，筮得《无妄》之《益》。</p><p>断曰：四近尊位，德秉乾刚，正合贵显身位。今占得第四爻，曰“可贞无咎”，在贵显德位俱优，功业素著，无复丝毫妄念；恐民在下，有以妄动干进，全在贵显坚贞而镇定之，得“无咎”也。</p><h2 id="九五解" tabindex="-1">九五解 <a class="header-anchor" href="#九五解" aria-label="Permalink to “九五解”">​</a></h2><p>“疾”犹灾也。五动体《坎》，《坎》为疾，故曰疾。疾之来也，有由自致者，有因天时而非自致者，非由自致而疾者，即所谓“无妄之疾”也。“无妄之疾”，如在天为日之食，风之暴，雨之淫，雷之迅，皆一时阴阳之偏，偶触而来，时过则平，未可以药救也。在人，“无妄之疾”亦犹是焉，不容以药治之也，故曰“勿药有喜”。“有喜”，谓疾去而为喜也。当疾之时，以药治之耳，五爻刚中得位，天德全，《无妄》之至者也，复何遗憾？爻之取象于疾者，盖以汤之幽夏台，文之囚羑里，或有为盛德之累者焉。此则谓无妄之疾也，顺以守之，祸患自释，即“勿药”之义焉。《象传》曰“无妄之药，不可试也，”“无妄之疾”，本非真疾，药之反成疾矣，故曰“不可试”，慎之至也。</p><h2 id="九五占" tabindex="-1">九五占 <a class="header-anchor" href="#九五占" aria-label="Permalink to “九五占”">​</a></h2><p>○　问时运：目下气运当正，意外之事，不必介意，全乎在我而已。</p><p>○　问商业：凡一时物价，无故上落，皆无害商业，过时自平，切勿扰动。</p><p>○　问家宅：防有风扫雪压倾圯之患，然无大害，致有喜兆。</p><p>○　问战征：防军队中有时疫流行之患，宜洁净营屯，勿妄用药。无咎。</p><p>○　问行人：恐中途有涉意外之事，然即归来</p><p>○　问讼事：有意外牵涉，不辩自释。</p><p>○　问六甲：生男。</p><p>○　问失物：不寻自得。</p><h2 id="九五案例" tabindex="-1">九五案例 <a class="header-anchor" href="#九五案例" aria-label="Permalink to “九五案例”">​</a></h2><p>明治二十二年，占某贵显气运，筮得《无妄》之《噬嗑》。</p><p>断曰：五爻阳刚中正，下与二应，可谓《无妄》之至者也。今占得此爻，知某贵显德高望隆，复有何病？但道高招谤，或遭意处之嫌，是即“无妄之疾”也。宜勿与辩，逾时自释，若一为计较，转致多事，故曰“无妄之疾，勿药有喜”。某贵显不用此占，遂酿纷纭，翌年遂罢职闲居。</p><p>明治十五年八月，余弟德右卫门，患大肠痞结，聘医师守永某，乞诊服药，数日不愈。某曰：是非施截解术，不可治也。谋之佐藤国手，余复为占施术之适否，筮得《无妄》之《噬嗑》。</p><p>断曰：“无妄之疾”，非自致也。今弟之疾，亦自然而发，非关自致。爻曰“勿药有喜”，盖为不假人治也，是宜安养任其自然，三周间（《震》之数为三八）后，必可愈快。后服补药，不复施术，三周后，果得痊治。</p><p>占明治三十年海军之气运，筮得《无妄》之《噬嗑》。</p><p>断曰：《无妄》全卦，卦德为真实无妄，括言之曰正。《彖》辞曰“非正有眚”，眚灾害也，故《说卦》曰“无妄灾也”。今占得五爻，曰“无妄之疾，勿药有喜，”“无妄之疾”，犹言意外之灾也，恐海军中于九十两月中，必有非常之惊异也。此事非关人为，实由天意，非可强也。后横须贺镇守府长官相浦中将，巡见北海道炭山，余在汽车相晤，告以此占，中将如不介意。然至九月，闻扶桑舰沉没豫海，占兆乃验。</p><h2 id="上九解" tabindex="-1">上九解 <a class="header-anchor" href="#上九解" aria-label="Permalink to “上九解”">​</a></h2><p>上爻阳居卦之终，为《无妄》之极，极而复行，行必有眚，有何利焉！《彖》辞所谓“非正有眚”，盖指上也。上与三应，三为“邑人”，上为“行人”，三之灾，自上致之；三既被灾，上岂能无眚乎？《象》曰“穷之灾也”，位已上穷，复欲进行，是穷极而为害也。</p><h2 id="上九占" tabindex="-1">上九占 <a class="header-anchor" href="#上九占" aria-label="Permalink to “上九占”">​</a></h2><p>○　问时运：好运已终，宜安守勿动，动则终凶。</p><p>○　问商业：历来贸易，颇称得利，兹值岁终，或当时令交换之际，宜暂静守，切勿再进，防有损耗。</p><p>○　问家宅：此虽旧宅，居之则吉，慎勿他迁，迁则有眚</p><p>○　问战征：地步已极，不可复进，进则有害。</p><p>○　问疾病：必是老年，宜颐养自适。</p><p>○　问行人：即日可归，归后切勿出行。</p><p>○　问六甲：生男。</p><p>○　问失物：恐穷追不得。</p><h2 id="上九案例" tabindex="-1">上九案例 <a class="header-anchor" href="#上九案例" aria-label="Permalink to “上九案例”">​</a></h2><p>每年一月，余必避寒于热海。明治二十二年一月，静罔县知事关口隆吉君偶巡回县下，同宿汤户某家。关口氏为幕府旧士，尝学于昌平校，夙具才学，维新之际，五棱廓将帅之一也。氏索余占当岁气运，筮得《无妄》之《随》。</p><p>断曰：异哉，何其爻象之凶也！《说卦》曰“无妄灾也”，“灾”谓天灾，是天降之灾也。爻辞曰“行有眚，无攸利”，观此爻象，恐于行路中，忽遭祸变。“眚”，损也，必身体大有损伤。《象》曰“穷之灾也”，言灾害之至极也。余就占象直言，吉人天相，君勿过虑，慎之而已。关口氏闻之，面为失色。后见新闻纸报道，阿部川城之越间汽车冲突，关口知事被伤，政府闻之，遣侍医偌藤桥本医治。余阅报惊曰：果哉关口君，竟罹“无妄之灾”！愈感《易》占之神知，悚然者久之。一日得静罔警部长相原安次郎氏来函云，知事被灾，果应热海之占，不堪敬服。今欲再占知事之生命如何，烦为一筮回告。筮得《泰》之《大畜》。爻辞曰：“上六：城复于隍。”《象传》曰：“诚复于隍，其命乱也。”断曰：《泰》为天地交泰之卦，今占得上爻，是《泰》之将终，转而为《否》之时。“城复于隍”者，倾毙之象；“其命乱”者，谓命之不全也。即以此旨答之。时见者多怪余断之凶，曰：据医师诊断，有回生之兆，是新闻纸所报也，贵断毋乃过乎？余曰：诸君有疑，请俟诸他日。未几，关口氏讣至，于是当时诸君皆感服《易》占之妙用。后复晤相原氏，氏曰当时得子返书，已知事不起。怀书往访，知事谓余曰：今春热海游浴之时，高岛氏占象，预诫余之遭难，果若此，殆夫命也。近得医治，言可回生，尚为幸耳。余因叹息，不忍以贵占出示。谈及当时车变云，此日知事至静罔停车场，适将发铁石杂车，知事急麾之，驿吏命暂停，使知事乘之。迨进行二里余，至铁路屈曲处，忽前面汽车蓦地驶来，与之冲突，轰然一声，积载货物，悉飞天外，乘客中即死一人，负伤二人，知事其一也。余本同行，因知事心急，单身乘车，余未知之，得免于祸，幸哉！翌年春，晤关口氏养子某于热海，曰：亡父平素语足下《易》学，去岁自热海归，每闲居读君《易》断，至《无妄》一卦，常三复不已。</p>',112)])])}const m=p(i,[["render",l]]);export{b as __pageData,m as default};
